/ {
	aliases {
		// Define 'spio' as an alias to the simulated SPI controller.
		// This resolves the "undefined node label 'spio'" error.
		spio = &spi_sim0;
	};
};

// Enable the simulated SPI controller and define the ICM42688 sensor as its child.
&spi_sim0 {
	status = "okay";

	icm42688_0: icm42688@0 {
		compatible = "tme,icm42688";
		reg = <0>; // Chip select 0
		spi-max-frequency = <1000000>; // Example frequency, adjust as needed
		label = "ICM42688";
	};
};
